<script setup>import { Head,Link,useForm } from '@inertiajs/vue3'; import AppButton from '../../../Components/AppButton.vue'; import EmptyState from '../../../Components/EmptyState.vue'; import AppLayout from '../../../Layouts/AppLayout.vue'; defineProps({tasks:Array,emptyMessage:String,canUpdate:Boolean});
// Seuls les deux gestes du quotidien sont proposés ici ; le reste se fait depuis la fiche de la tâche.
const quickTransitions = ['en_cours', 'terminee'];
const statusForm = useForm({ status: '' });
function changeStatus(task, status) { statusForm.status = status; statusForm.patch(`/taches/${task.id}/etat`, { preserveScroll: true }); }
</script>
<template><Head title="Mes tâches du jour"/><AppLayout title="Mes tâches du jour" back-label="Toutes les tâches" back-href="/taches"><div class="grid min-w-0 gap-5"><h1 class="text-page-title">Mes tâches du jour</h1><ul v-if="tasks.length" class="grid min-w-0 gap-3"><li v-for="task in tasks" :key="task.id" class="grid min-w-0 gap-2 rounded-xl border border-separator p-4"><Link :href="`/taches/${task.id}`" class="break-words font-semibold text-primary">{{ task.title }}</Link><p>{{ task.status_label }} · {{ task.priority_label }}</p><div v-if="canUpdate" class="flex flex-wrap gap-2"><AppButton v-for="transition in task.transitions.filter((item) => quickTransitions.includes(item.value))" :key="transition.value" type="button" :variant="transition.value === 'terminee' ? 'principal' : 'secondaire'" :busy="statusForm.processing" @click="changeStatus(task, transition.value)">{{ transition.value === 'terminee' ? 'Marquer terminée' : 'Commencer' }}</AppButton></div></li></ul><EmptyState v-else :title="emptyMessage" reason="Les tâches qui vous sont confiées et arrivent à échéance aujourd’hui apparaîtront ici. Retrouvez les autres dans « Toutes les tâches »."/></div></AppLayout></template>
